```c
#include <stdio.h>
int fib(int n) {
    if (n <= 1) return n;
    return fib(n - 1) + fib(n - 2);
}

int main() {
    int input;
    scanf("%d", &input);
    printf("%d", fib(input));
    return 0;
}
```

